-- Generated by execution/homework_sql.ts from docs/homework-2026-27/final/qaidah-hw6.json.
-- Loads homework 306 for 2026/27. Review, then apply with execution/apply_migration.ts.
-- Idempotent: re-running replaces the same papers again.

do $guard$ begin
  if exists (select 1 from submissions s join homeworks h on h.id = s.homework_id
             join auth.users u on u.id = s.student_id
             where h.number in (306) and coalesce(u.email, '') not like '%@bsms-demo.test') then
    raise exception 'a real student has work on a homework this load replaces; stop and ask';
  end if;
end $guard$;

-- Demo work on the replaced papers (answers, voice notes, attempts cascade).
delete from submissions where homework_id in (select id from homeworks where number in (306));
delete from questions where homework_id in (select id from homeworks where number in (306));

-- ── Homework 306: Sukūn (3 marks, 3 questions)
insert into homeworks (number, title, series, total_marks, is_graded, week_id, due_at, course_id, ordinal)
select 306, $q$Sukūn$q$, 'qaidah', 3, true, w.id, w.due_at, c.id, 6
  from weeks w, courses c where w.term_id = 1 and w.number = 6 and c.key = 'qaidah'
on conflict (number) do update set title = excluded.title, series = excluded.series, total_marks = excluded.total_marks,
  is_graded = true, course_id = excluded.course_id, ordinal = excluded.ordinal;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 1, 'text', 'manual', $q$Read the following words and record yourself. Make sure you properly observe the characteristics of qalqalah and hams.$q$, 1, false, true, null, null, false
  from homeworks where number = 306;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 2, 'text', 'manual', $q$Read the following words and record yourself. Make sure you properly observe the characteristics of qalqalah and hams.$q$, 1, false, true, null, null, false
  from homeworks where number = 306;
insert into questions (homework_id, position, qtype, scoring, prompt, points, is_bonus, is_task, options, rubric, needs_key)
select id, 3, 'text', 'manual', $q$This is meant to be difficult, but it is there to push you and brings together what has been covered so far. Practise beforehand, then record what you believe is the correct way to recite each box.$q$, 1, false, true, null, null, false
  from homeworks where number = 306;

-- Audio needs questions.media (migration 0048); skipped until it exists.
do $media$ begin
  if exists (select 1 from information_schema.columns where table_schema = 'public' and table_name = 'questions' and column_name = 'media') then
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw6-1.jpg","alt":"Twenty two-letter words, each ending in a letter with a sukūn","width":960,"height":547}]}$q$::jsonb where position = 1 and homework_id = (select id from homeworks where number = 306);
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw6-2-1.jpg","alt":"Sixteen words with a sukūn in the middle or at the end","width":960,"height":552},{"src":"/images/homework/qaidah/hw6-2-2.jpg","alt":"Sixteen more words with a sukūn","width":960,"height":546}]}$q$::jsonb where position = 2 and homework_id = (select id from homeworks where number = 306);
    update questions set media = $q${"images":[{"src":"/images/homework/qaidah/hw6-3-1.jpg","alt":"Three short phrases from the Qur'an","width":960,"height":126},{"src":"/images/homework/qaidah/hw6-3-2.jpg","alt":"Three more short phrases from the Qur'an","width":960,"height":129},{"src":"/images/homework/qaidah/hw6-3-3.jpg","alt":"Three more short phrases from the Qur'an","width":960,"height":113}]}$q$::jsonb where position = 3 and homework_id = (select id from homeworks where number = 306);
  end if;
end $media$;

select number, title, total_marks, (select count(*) from questions q where q.homework_id = h.id) as questions
  from homeworks h where number in (306) order by number;
